# aeneid-055 (VII.601-705): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Belli portae. Itala agmina'
PART = 'The Gates of War and the Muster of Italy (VII.601–705)'
TITLE_EN = 'The Gates of War and the Muster of Italy — Aeneid VII.601–705'
ABOUT = ("Latinus has refused to declare war, and Virgil pauses to explain the rite he is refusing: the twin Gates of War, "
"the shrine of Janus that the consul of Virgil's own Rome unbars in ceremonial dress when the senate votes for war, and that "
"Augustus had lately closed in token of peace. The old king will not touch them, so Juno comes down from heaven and bursts them "
"open with her own hand. At once all Italy, quiet until now, is ablaze: men polish shields and whet axes, five cities set up their "
"anvils, ploughshares and pruning-hooks are forged into swords, and the trumpets sound. Then, as Homer did before his catalogue of "
"the ships in Iliad 2, Virgil calls on the Muses and begins the great roll-call of the Italian leaders who will fight Aeneas: "
"Mezentius, the Etruscan scorner of the gods, with his son Lausus, who deserved a better father; Aventinus, son of Hercules, in his "
"father's lion-skin; the Argive brothers from Tibur, charging like Centaurs down a mountain; Caeculus, the hearth-born son of Vulcan, "
"with his half-armed hill-folk; and Messapus, Neptune's son, whom no weapon can wound, whose columns march singing like swans. "
"The catalogue continues in the next part with Clausus, Halaesus, Oebalus, Ufens, Umbro, Virbius, Turnus and Camilla.")

U = [
(603, 'Martem,',
 "There was a custom in Hesperian Latium, which from the first the cities\nof Alba kept as holy, and now the greatest of things,\nRome, keeps, whenever first they stir Mars into battles,",
 "There was a custom in Hesperian Latium, held sacred from the first by the cities of Alba and kept now by Rome, the greatest power in the world, whenever they first rouse the War-god to battle,",
 """Virgil stops the story to explain a Roman rite: the custom 'was' already in Latium, passed to Alba Longa (the city of Aeneas's son) and so to Rome, the chain of the poem's opening lines (I.6–7). 'quem… sacrum… coluere', 'which they kept as sacred'; 'coluere' = 'coluerunt', the short perfect in '-ere' you have met constantly. 'maxima rerum Roma', 'Rome, greatest of things', a phrase of Virgil's own pride. 'cum prima movent' = 'cum primum', 'as soon as', with 'prima' adverbial; the subject is the Romans, 'they'. 'Martem' is war itself, the god standing for his work (metonymy)."""),
(606, 'signa.',
 "whether on the Getae to bring by hand tearful war\nor on Hyrcanians or Arabs they prepare, or to march to the Indians\nand to follow the Dawn and from the Parthians to demand back the standards.",
 "whether they are making ready to carry war and its tears to the Getae, the Hyrcanians or the Arabs, or to march on India, follow the sunrise, and claim back the standards from the Parthians.",
 """The list is of Augustus's frontiers, not Latinus's: the Getae on the lower Danube, the Hyrcanians by the Caspian, the Arabs, the Indians at the edge of the world ('Auroram sequi', to chase the dawn eastward). 'Getis… Hyrcanisve Arabisve' are datives with 'inferre bellum', 'to bring war upon'. 'Parthosque reposcere signa', 'to demand back the standards from the Parthians', takes the double accusative of asking: these are the eagles lost by Crassus at Carrhae in 53 BC, recovered by Augustus through diplomacy in 20 BC, one of the great boasts of his reign. 'lacrimabile', 'tearful', 'bringing tears'."""),
(608, 'Martis;',
 "There are twin gates of war (so by name they call them),\nhallowed by religious awe and by dread of savage Mars;",
 "There are two Gates of War — that is the name men give them — made holy by reverence and by dread of cruel Mars;",
 """The Gates of War belong to the shrine of Janus Geminus in the Roman Forum: a small bronze gateway with doors at each end, open in war and shut in peace. Tradition said Numa built it and that it had been shut only once more (after the First Punic War) before Augustus closed it in 29 BC; Jupiter foretells the closing in Book I ('claudentur Belli portae', I.293–294). 'sic nomine dicunt', 'so they call them by name', the parenthesis of a poet explaining an old word. 'religione', 'religious awe', the scruple that keeps hands off a holy thing; 'formidine Martis', fear of the god inside."""),
(610, 'Ianus:',
 "a hundred bronze bars shut them, and the everlasting strength\nof iron, nor does the guardian Janus stand away from the threshold:",
 "a hundred bolts of bronze and the unyielding strength of iron keep them shut, and Janus never leaves his post upon the threshold:",
 """'vectes', bars or bolts. 'aeterna ferri robora', literally 'the everlasting oak-strengths of iron': 'robur' is oak, then any hardness, so the phrase means massive iron fastenings. Janus, the two-faced god of doorways and beginnings (January is his month), stands guard as 'custos'; 'absistit limine', 'stands off from the threshold', ablative of separation. Note 'aerei' scanned as three syllables, 'ae-re-i'."""),
(614, 'pugnas;',
 "these, when fixed sits with the fathers the resolve for fighting,\nhe himself, in Quirinal robe and Gabine girding\nconspicuous, unbars — the grating thresholds — the consul;\nhe himself calls forth the fighting;",
 "these, once the senate has firmly resolved on war, the consul himself, conspicuous in the robe of Quirinus and the toga girt in the Gabine fashion, unbars on their grating hinges; he himself summons the battle;",
 """'has' (the gates) is the object of 'reserat', and 'stridentia limina' repeats it: 'unbars these… the creaking thresholds'. 'certa sedet patribus sententia', 'a fixed resolve sits with the fathers', the senators; 'patribus' is dative of the person concerned. The 'Quirinalis trabea' is the striped state robe associated with Romulus deified as Quirinus. The 'cinctus Gabinus' is a way of wearing the toga with a fold drawn over the head and the rest girt tight round the waist, said to come from the town of Gabii and worn at sacrifices and declarations of war. 'ipse… ipse', anaphora: the consul in person does every part. Virgil sets a rite of the Republic in the age of Latinus, an anachronism he makes on purpose."""),
(615, 'rauco.',
 "then follows the rest of the young manhood,\nand the bronze horns breathe together in hoarse assent.",
 "then the rest of the young men take up the cry, and the bronze horns blare out together their hoarse agreement.",
 """'cetera pubes', 'the rest of the youth', the men of fighting age, who repeat the consul's call. 'conspirant', literally 'breathe together', from 'spiro': the horns sound in unison, and the word also suggests agreement, which 'adsensu', 'with assent', makes explicit. 'aereaque' elides into 'adsensu'; 'cornua' are curved horns, the instruments of the Roman army."""),
(617, 'portas.',
 "By this custom then too on the Aeneadae to declare wars Latinus\nwas being bidden, and to unbar the grim gates.",
 "By this custom Latinus too was now being pressed to declare war on the sons of Aeneas and to throw open the gates of grief.",
 """'Hoc… more', 'by this custom', framing the sentence. 'Aeneadis', 'the Aeneadae', the followers of Aeneas, dative with 'indicere bella', 'to declare war upon'. 'iubebatur', imperfect: they kept urging him, and he kept refusing (VII.594–600, the end of the previous part). 'tristis' is accusative plural with 'portas', Greenough's '-is' (= 'tristes')."""),
(619, 'umbris.',
 "The father held back from the touch, and turning away fled\nthe foul office, and hid himself in blind shadows.",
 "The old king would not lay a hand on them; he turned away, shrank from the hateful task, and buried himself in the darkness of his halls.",
 """'pater', the old king, father of his people. 'abstinuit tactu', 'kept from touching', ablative of separation. 'refugit' takes a direct object here, 'fled from the foul ministry': 'ministeria' is the service or office of opening the gates. 'caecis… umbris', 'blind shadows', the darkness where no one sees him, echoing 'saepsit se tectis' in VII.600."""),
(622, 'postes.',
 "Then the queen of the gods, gliding down from heaven, the lingering\ngates pushed with her own hand, and, the hinge turned,\nof War the iron-bound doorposts bursts Saturnia.",
 "Then the queen of the gods herself came gliding down from the sky and thrust the reluctant gates open with her own hand; Saturn's daughter swung them on their pivots and burst the iron-bound doors of War.",
 """'regina deum' ('deum' = 'deorum') and 'Saturnia' are both Juno, daughter of Saturn; she does what the king refuses, 'ipsa manu', with her own hand. 'morantis', accusative plural with 'portas', the gates that 'delay', that hang back. 'cardine verso', ablative absolute, 'the pivot turned': Roman doors swung on pins set in sockets. 'rumpit', historic present after the perfect 'impulit'. Line 622 echoes the old poet Ennius, whose Discord 'broke open the iron-bound doorposts and gates of War' ('Belli ferratos postes portasque refregit'), lines Horace quotes as the very type of true poetry. The Latin Library prints 'postis', the same word."""),
(623, 'ante;',
 "Ablaze is Ausonia, unroused and unmoving before;",
 "Italy, unstirred and unmoving till now, is all aflame;",
 """'Ardet', put first: Italy catches fire. 'Ausonia', a poetic name for Italy, from the old Ausones. 'inexcita… atque immobilis ante', 'unroused and motionless before', describes the land up to this moment; 'inexcita' elides into 'Ausonia'. Greenough's print has a semicolon here followed by a capital 'Pars' in the next line, an odd pairing: either the stop or the capital may be a slip (other editions have a colon or full stop). The sense is the same either way, so the print is kept and simply flagged."""),
(625, 'requirunt.',
 "Some on foot make ready to go over the plains, some, tall upon lofty\nhorses, dusty, rage; all call for arms.",
 "Some make ready to march across the plains on foot, others storm along high on their horses in clouds of dust; every man is calling for weapons.",
 """'Pars… pars', 'some… others', with singular verbs ('parat', 'furit'). 'pedes' is the noun 'pedes, peditis', 'a foot-soldier', in apposition: 'some, as infantry'. 'arduus altis… equis', 'towering on high horses', and 'pulverulentus', 'dusty', describe the horseman, singular for the group. 'campis', ablative of the way by which. 'requirunt', 'call for', 'demand': arms long laid by are wanted again."""),
(627, 'secures;',
 "Some their smooth shields and gleaming darts scour\nwith rich lard, and work on the whetstone their axes;",
 "Some scour their polished shields and bright javelins with rich grease and grind their axes on the whetstone;",
 """'levis' is accusative plural of 'levis' with a long e, 'smooth, polished' (not 'levis', 'light'). 'tergent', 'wipe, scour'. 'arvina pingui', 'with fat lard', ablative of means: grease to clean and protect the metal. 'subigunt in cote', 'work them down on the whetstone', sharpen. The Latin Library's 'securis' for 'secures' is only spelling of the accusative plural."""),
(628, 'tubarum.',
 "and to carry the standards delights, and to hear the sounds of the trumpets.",
 "it is a joy to bear the standards and to hear the trumpets call.",
 """'iuvat', impersonal, 'it pleases', with two infinitives as subject, 'ferre' and 'audire'. 'sonitus tubarum', the blare of the straight war-trumpet ('tuba'), distinct from the curved 'cornua' of line 615. The tone is of men who have been eager for this."""),
(631, 'Antemnae.',
 "Five great cities, no less, their anvils set up,\nrenew weapons, mighty Atina and proud Tibur,\nArdea and the Crustumeri and tower-crowned Antemnae.",
 "Five great cities, no fewer, set up their anvils and forge their weapons anew: mighty Atina, proud Tibur, Ardea, Crustumerium, and Antemnae crowned with towers.",
 """'adeo' stresses the number, 'five whole cities'. 'positis incudibus', ablative absolute, 'anvils set up'. 'tela novant', 'make new their weapons'. The towns are all old Latin, Volscian or Sabine places: Atina in the Volscian hills, Tibur (Tivoli), Ardea (Turnus's own city), Crustumerium (here 'Crustumeri', a plural name) and Antemnae near Rome, 'turrigerae', 'tower-bearing'. Elision runs through the last line, 'Crustumerique et'."""),
(633, 'cratis;',
 "Safe coverings they hollow for heads, and bend the willow\nwickerwork of shields;",
 "They hollow out helmets to guard the head and bend willow frames for the bossed shields;",
 """'Tegmina tuta capitum', 'safe coverings of heads', a poet's way of saying helmets, hammered hollow ('cavant'). 'salignas umbonum cratis', 'willow wickerwork of bosses': 'umbo' is the central boss of a shield, standing for the shield itself, whose frame was woven of withies and covered with hide. 'cratis', accusative plural ('crates')."""),
(634, 'argento;',
 "others breastplates of bronze\nor smooth greaves out of pliant silver draw;",
 "others beat out breastplates of bronze, or smooth greaves of pliant silver;",
 """'alii', 'others', after the unstated subject of the previous clause. 'thoracas', the Greek accusative plural in '-as' of 'thorax', 'breastplate'. 'aenos' = 'aeneos', 'of bronze', the contracted form. 'levis ocreas', 'smooth greaves' (long e again, as in 626). 'lento… argento', 'from pliant silver', ablative of material; 'ducunt', 'draw out', hammer thin. Silver greaves are heroic finery: Homer's heroes wear greaves with silver ankle-clasps."""),
(636, 'cessit amor;',
 "of the ploughshare to this, and of the sickle, the honour, to this all the plough's\nlove has yielded;",
 "all the honour once paid to share and pruning-hook, all the love of the plough, has given place to this;",
 """'huc… huc', 'to this… to this', anaphora: all is turned to arms. 'vomeris… et falcis honos', 'the honour of the ploughshare and the pruning-hook'; 'falx' is the curved blade for vines and hedges. 'cessit', 'has given way'. The farmer of the Georgics becomes a soldier; Virgil had written the same turn in Georgics 1.508, 'curvae rigidum falces conflantur in ensem', 'curved sickles are fused into the stiff sword'."""),
(636, 'enses.',
 "they cook again their fathers' swords in furnaces.",
 "they melt down their fathers' swords in the furnaces and forge them anew.",
 """'recoquunt', 'cook again', put back into the fire to temper and reshape. 'patrios… enses', 'ancestral swords', laid up since the last war, which suits the long peace of Latinus's reign. 'fornacibus', ablative of place where. The Latin Library's 'ensis' is only the alternative accusative plural."""),
(637, 'sonant;',
 "And now the war-trumpets sound;",
 "Now the trumpets sound for battle;",
 """'Classica', the trumpet signal, then the trumpets that give it; originally the call that summoned the 'classes', the divisions of the people under arms. 'iamque', 'and now', marks the next stage."""),
(637, 'signum.',
 "goes for the war the tablet, the watchword.",
 "the watchword passes down the ranks for war.",
 """'tessera', a small tablet on which the watchword was written and passed from hand to hand through the camp; 'signum', 'the sign, the password', stands in apposition. 'it bello', 'goes out for war', dative of purpose (or 'in the war'). Another Roman military detail set in heroic Italy."""),
(640, 'ense.',
 "This man a helmet from the house in haste snatches, that one the snorting\nhorses to the yokes forces, and a shield, and with gold triple-twilled\na corslet he puts on, and with a trusty sword girds himself.",
 "One man snatches his helmet from the house in a hurry, another forces his snorting horses under the yoke, buckles on his shield and his corslet woven triple with gold, and girds a trusty sword at his side.",
 """'Hic… ille', 'this one… that one'. 'tectis', 'from the house', ablative of separation. 'frementis… equos', 'snorting horses', accusative plural; the Latin Library prints 'trementis', 'trembling', a different picture of the horses but the same scene. 'trilicem', 'triple-twilled', of mail woven with three threads (compare Homer's 'well-woven' armour); 'auro' goes with it, 'worked with gold'. 'induitur' and 'accingitur' are passives used as middles, 'puts on himself', 'girds himself', the first with an accusative object: a Greek construction Virgil uses often. The arming of a warrior is a standard Homeric scene, here shrunk to a line or two."""),
(644, 'armis.',
 "Throw open now Helicon, goddesses, and set your songs moving:\nwhat kings were roused to war, what battle-lines following each\nfilled the plains, with what men the Italian, even then,\nbountiful earth flowered, with what arms it blazed.",
 "Throw Helicon open now, goddesses, and stir up your songs: tell what kings were roused to war, what armies followed each of them and filled the plains, with what heroes the kindly Italian earth was already blossoming then, and with what arms it blazed.",
 """A fresh invocation of the Muses, the 'deae', before the catalogue, as Homer calls on them before the Catalogue of Ships ('Tell me now, Muses who have homes on Olympus', Iliad 2.484–493). 'Helicona' is the Greek accusative of Helicon, the Muses' mountain in Boeotia: 'open' it as if it were a treasure-house of song. The four indirect questions ('qui… quae… quibus… quibus') put their verbs in the subjunctive: 'complerint' = 'compleverint', the syncopated perfect; 'floruerit', 'arserit'. 'iam tum', 'even then', in the earliest age, before Rome. Virgil makes a second catalogue, of Aeneas's Etruscan allies, in Book X, with its own invocation."""),
(645, 'potestis:',
 "For you both remember, goddesses, and can recall it:",
 "For you, goddesses, remember, and you have the power to tell:",
 """'Et… et', 'both… and'; 'enim' gives the reason for the appeal. The pairing 'meministis… memorare' plays on memory and telling: the Muses are daughters of Memory (Mnemosyne), so they both keep the past and can bring it out. This follows Homer's invocation closely: 'for you are goddesses, and are present, and know all things'."""),
(646, 'aura.',
 "to us scarcely a thin breath of report glides down.",
 "to us there drifts down barely a faint breath of the story.",
 """The other half of Homer's contrast: 'but we hear only report and know nothing'. 'famae… aura', 'a breeze of rumour', the faintest whisper of tradition, and 'perlabitur', 'glides all the way down' through the ages, with 'vix', 'barely'. The colon in line 645 sets this against the Muses' full knowledge."""),
(648, 'armat.',
 "First enters the war, from the Tyrrhene shores, harsh,\nthe scorner of the gods, Mezentius, and arms his columns.",
 "First into the war, from the coasts of Etruria, comes fierce Mezentius, the despiser of the gods, and arms his columns.",
 """The catalogue begins with its darkest figure. Mezentius is the Etruscan tyrant of Caere, driven out by his own people for his cruelty (Evander tells the story in Book VIII) and now fighting beside Turnus. 'Tyrrhenis… ab oris', 'from the Etruscan coasts'. 'contemptor divom', 'despiser of the gods', his fixed title: the opposite of pious Aeneas. 'divom' = 'divorum', the old genitive plural (the Latin Library spells it 'diuum'). 'asper', 'harsh, savage'."""),
(651, 'ferarum,',
 "His son beside him, Lausus, than whom handsomer another\nthere was not, excepting the body of Laurentine Turnus,\nLausus, tamer of horses and subduer of wild beasts,",
 "Beside him is his son Lausus — no one was handsomer, save only Turnus of Laurentum — Lausus, the breaker of horses, the subduer of wild beasts,",
 """'Filius huic', 'a son to him', dative of possession with the verb left out. 'quo pulchrior alter non fuit', 'than whom no other was more handsome': 'quo' is ablative of comparison. 'excepto… corpore Turni', ablative absolute, 'the form of Turnus excepted'; 'corpus' for the person, as in Greek. Compare Homer's Nireus in the Catalogue of Ships, handsomest of the Greeks after Achilles. 'Laurentis', 'of Laurentum', used loosely: Turnus is a Rutulian of Ardea, but Laurentum is the Latin capital and stands for the region. 'equum' = 'equorum'; 'equum domitor' renders Homer's 'tamer of horses'. The repetition of 'Lausus' marks the poet's affection."""),
(654, 'esset.',
 "leads, from the Agylline city, following in vain,\na thousand men, worthy to have been happier in his father's\nrule, and to have had a father not Mezentius.",
 "who leads a thousand men that followed him from the city of Agylla, all to no purpose — a youth who deserved more joy of his father's rule, and deserved a father other than Mezentius.",
 """'Agyllina… ex urbe', 'from the Agylline city', Agylla, the old Greek name of Caere (modern Cerveteri). 'nequiquam… secutos', 'having followed in vain': they left the city that expelled Mezentius to follow the son, and it will not save him. 'dignus, qui… esset', a relative clause of characteristic after 'dignus', 'worthy to be': 'worthy to be happier in a father's rule, and to have a father who was not Mezentius'. 'patriis… imperiis', 'his father's commands'. Lausus dies in Book X shielding his father, and Aeneas, who kills him, grieves over him."""),
(658, 'hydram;',
 "After these, his chariot marked with the palm over the grass\nand his victorious horses displays, sprung from handsome Hercules,\nhandsome Aventinus, and on his shield his father's device,\na hundred snakes and a hydra girt with serpents, he bears;",
 "After them handsome Aventinus, son of handsome Hercules, parades across the turf his chariot decked with the palm and his victorious horses, and on his shield he bears his father's emblem, a hundred snakes and the Hydra ringed with serpents;",
 """'insignem palma… currum', 'a chariot distinguished by the palm', the prize of victory in the race: Aventinus comes as an athlete. 'ostentat', 'shows off'. 'satus Hercule pulchro pulcher Aventinus', 'sprung from handsome Hercules, handsome Aventinus': the adjective is repeated across the line-break to bind son to father; 'Hercule' is ablative of source with 'satus'. 'insigne paternum', 'his father's device', the Hydra of Lerna, the many-headed water-snake of Hercules's second labour; 'centum angues' is in apposition to it ('angues' is spelled 'anguis' in the Latin Library, the same plural). 'gerit' governs both 'insigne' and the apposition."""),
(663, 'Hiberas.',
 "him in the wood of the Aventine hill the priestess Rhea\nin stealthy birth brought forth beneath the borders of light,\na woman mingled with a god, after, to the Laurentine, as victor,\nGeryon slain, the Tirynthian came, the fields,\nand in the Tyrrhene river washed the Iberian cattle.",
 "the priestess Rhea bore him in secret in the woods of the Aventine hill and brought him into the light, a mortal woman joined with a god, when the hero of Tiryns, victorious after killing Geryon, had reached the fields of Laurentum and was washing his Spanish cattle in the Tuscan river.",
 """'quem', connecting relative, 'him'. 'collis Aventini silva', 'in the wood of the Aventine hill', ablative of place without a preposition: the son is named after the hill of his birth. 'Rhea sacerdos' is an unknown priestess, not Rhea Silvia, mother of Romulus. 'Rhea' is two syllables. 'furtivum partu', 'stealthy in birth', born in secret. 'sub luminis edidit oras', 'brought forth into the shores of light', a phrase from Lucretius. 'mixta deo mulier', 'a woman united with a god': the union with Hercules is stated plainly, with no hint of force. 'Tirynthius', 'the man of Tiryns', Hercules, who grew up in that Argive city. He was driving home the cattle of Geryon, the three-bodied giant of the far west whom he killed in his tenth labour, which is why the cattle are 'Hiberas', 'Iberian, Spanish'; on the way he passed through Latium and killed Cacus, a story told in Book VIII. 'Tyrrheno… in flumine', the Tiber, which flows out of Etruria. 'extincto' is spelled 'exstincto' in the Latin Library."""),
(665, 'Sabello.',
 "Javelins in hand and cruel pikes they carry into the wars,\nand fight with tapering point and Sabellian spit.",
 "His men carry javelins and cruel sword-staves into battle, and fight with the tapering point and the Sabine spit-dart.",
 """The subject shifts to Aventinus's men. 'Pila', the heavy Roman javelin, anachronistic in Latinus's Italy. 'dolones', staves with a blade concealed inside, a kind of sword-stick or pike. 'tereti… mucrone', 'with a rounded, tapering point'. 'veru', literally 'spit', a slender iron-tipped javelin; 'Sabello', 'Sabellian', of the Sabine hill peoples."""),
(669, 'amictu.',
 "He himself on foot, swinging round him the huge covering of a lion,\nshaggy with terrible bristling mane, with white teeth,\nput on upon his head, thus the royal halls he was entering,\nrough, and bound at the shoulders in the garb of Hercules.",
 "He himself went on foot, wearing as a helmet the vast hide of a lion, wrapped about him, its fearsome shaggy mane and white teeth still on it; so he came up to the king's palace, a rough figure, the mantle of Hercules knotted at his shoulders.",
 """'Ipse pedes', 'himself on foot', in contrast with the chariot of 655. The lion-skin is his father's emblem, the hide of the Nemean lion that Hercules wore with the head as a hood. 'torquens', 'twisting it round him'. 'impexum saeta', 'uncombed in its mane'. 'indutus capiti', 'having put it on his head', a middle participle with the dative of the place. 'umeros innexus', 'tied as to the shoulders', the Greek accusative of the part affected with a passive participle, a construction you will see often. 'subibat', imperfect: the picture of his arrival at Latinus's palace. 'tegumen' (Latin Library 'tegimen') is a spelling difference."""),
(673, 'feruntur:',
 "Then twin brothers the walls of Tibur leave,\na people named by the surname of their brother Tiburtus,\nCatillus and keen Coras, Argive youth,\nand in front of the foremost line among thick weapons they are borne:",
 "Then two brothers leave the walls of Tibur, a town named after their brother Tiburtus — Catillus and fierce Coras, young men of Argive stock — and they charge ahead of the front rank through the thick of the spears:",
 """Tibur was said to have been founded by three Argive brothers, sons (or grandsons) of the seer Amphiaraus: Tiburtus, who gave the town his name, Catillus and Coras. Hence 'Argiva iuventus', 'Argive youth'. 'gemini', 'two', 'a pair', not necessarily twins. 'fratris Tiburti dictam cognomine gentem', 'the people called by the name of their brother Tiburtus', in apposition to 'Tiburtia moenia'. 'acer', 'keen, fierce'; '-que… -que', the double connective. 'feruntur', 'are borne', the passive used of headlong motion, 'they rush'."""),
(676, 'rapido;',
 "as when two cloud-born, from the summit of a lofty mountain,\ncome down, Centaurs, Homole and snowy Othrys\nleaving at a swift run;",
 "as when two cloud-born Centaurs come down from a high mountain peak, leaving Homole and snowy Othrys at a racing gallop;",
 """A simile, introduced by 'ceu… cum', 'as when'. The Centaurs, half man and half horse, are 'nubigenae', 'cloud-born', children of Ixion and the cloud that Jupiter shaped in the likeness of Juno. Homole and Othrys are mountains of Thessaly, the Centaurs' country; 'Homolen' is a Greek accusative, and 'Othrymque' Greenough's Latinised accusative of Othrys. The picture of two warriors as wild mountain creatures crashing downhill is Homeric in kind."""),
(677, 'fragore.',
 "gives to them going the huge\nforest room, and with great crashing the thickets yield.",
 "the great forest makes way for them as they go, and the undergrowth gives before them with a mighty crashing.",
 """'dat… locum', 'gives place, makes way'; 'euntibus', dative of the participle of 'eo', 'to them as they go'. 'ingens silva' is split across the line. 'magno… fragore', ablative of manner, 'with a great crash': the sound of the line, with its hard c's and r's, carries the noise."""),
(681, 'Caeculus.',
 "Nor was the founder of the Praenestine city lacking,\nborn to Vulcan among the country herds a king\nand found on the hearth, as every age has believed,\nCaeculus.",
 "Nor was the founder of Praeneste missing: Caeculus, the king whom every age has believed to be the son of Vulcan, born among the cattle in the fields and found lying on a hearth.",
 """'Nec… defuit', 'nor was lacking', a catalogue formula. Praeneste (modern Palestrina) claimed Caeculus as founder. The ancient commentator Servius tells his story: a girl sitting by the hearth was struck by a spark and conceived; the baby was exposed and found beside a fire, and was called Caeculus, 'little blind one', for his small eyes, hurt by the smoke. 'Volcano genitum', 'begotten by Vulcan', the god of fire; 'focis', 'on the hearth', ablative of place. 'quem credidit omnis aetas', 'whom every generation has believed (to be)'. The name is held back to the start of line 681, in apposition to 'fundator' four lines earlier."""),
(681, 'agrestis:',
 "Him far and wide attends a legion of country folk:",
 "A rustic army throngs about him on every side:",
 """'legio', 'a legion', the Roman word used loosely of a levy of hill-farmers; 'agrestis' agrees with it, nominative singular. 'late', 'far and wide', over the countryside. The Latin Library places 'legio' differently in the line; the sense is the same. The colon introduces the list of the peoples who make up the band."""),
(685, 'Amasene pater.',
 "both the men who lofty Praeneste, and who the fields of Gabine\nJuno, and cool Anio, and, dewy with streams,\nthe Hernican rocks inhabit, whom rich Anagnia feeds,\nwhom, father Amasenus, you feed.",
 "the men of high Praeneste, of the fields of Gabine Juno, of the cold Anio and the Hernican rocks wet with streams; men whom wealthy Anagnia nourishes, and whom you nourish, father Amasenus.",
 """All these clauses describe the 'legio': 'quique… viri quique', 'both the men who… and those who', with one verb, 'colunt', at the end of line 684. 'arva Gabinae Iunonis', 'the fields of Gabine Juno', the land of Gabii, with its famous temple of Juno. 'Anienem' is the accusative of 'Anio', the Anio river (modern Aniene). The Hernici were a hill people east of Rome; Anagnia was their chief town. 'quos, Amasene pater' leaves 'pascis' to be understood, with a sudden address to the river-god of the Amasenus: apostrophe. The Latin Library prints 'pascis' for 'pascit' in 684, which would make the address begin a line earlier; Greenough's 'pascit' is the usual reading."""),
(686, 'sonant:',
 "Not to them all are arms,\nnor do shields or chariots resound:",
 "Not all of them have armour, nor do they rattle shields and chariots:",
 """'Non illis omnibus arma', supply 'sunt': 'not to all of them are there arms', the dative of possession (you have seen it often). 'arma' here means full armour, defensive gear. 'clipei currusve sonant', 'shields or chariots clash': they are poor mountain fighters, the opposite of Aventinus with his chariot."""),
(690, 'pero.',
 "the greatest part bullets\nof livid lead scatters, a part javelins carries,\ntwo in the hand, and tawny caps from the skin of a wolf\nas covering have for the head; the footprints of the left foot bare\nthey have made their custom, a rawhide boot covers the other.",
 "most of them sling bullets of dull grey lead, some carry two javelins in the hand; they have tawny caps of wolfskin to cover their heads, and it is their custom to go with the left foot bare, while a boot of raw hide covers the other.",
 """'pars maxima… pars', 'the greatest part… a part', with singular verbs. 'glandes liventis plumbi', 'acorns of livid lead', the almond-shaped bullets thrown by slingers; 'spargit', 'scatters'. 'spicula… bina', 'two javelins each', distributive. 'galeros', caps of hide. 'tegmen… capiti', 'as covering for the head', a predicate noun with a dative of purpose. 'vestigia nuda sinistri instituere pedis', 'they have made it their custom (to plant) the tracks of the left foot bare': 'instituere' = 'instituerunt'. 'crudus… pero', 'a boot of raw hide', covers 'altera' (understand 'vestigia'), the right. Compare the opposite custom of the Plataeans in Thucydides, who went out with only the left foot shod."""),
(694, 'retractat.',
 "But Messapus, tamer of horses, offspring of Neptune,\nwhom it is right for no one with fire nor to lay low with steel,\npeoples long since idle and to war unused\ncolumns to arms calls suddenly, and handles the sword again.",
 "But Messapus, the horse-tamer, son of Neptune, whom no one may bring down with fire or with steel, suddenly calls to arms peoples long sunk in ease and companies that had forgotten war, and takes up the sword once more.",
 """'equum domitor', the same Homeric title as Lausus's (651), apt for a son of Neptune, the god who gave the horse. 'quem neque fas… cuiquam… sternere', 'whom it is not permitted to anyone to lay low': he is invulnerable, a privilege of some sons of Neptune in legend; he does not die in the poem. 'igni… ferro', ablatives of means. 'resides', 'idle, sluggish', from long peace; 'desueta bello', 'unaccustomed to war', dative. 'retractat', 'handles again'. Ancient commentators said the old poet Ennius, who came from Messapia in the south, claimed Messapus as his ancestor."""),
(697, 'Capenos.',
 "These, the Fescennine battle-lines and the Aequi Falisci.\nThese hold the heights of Soracte and the Flavinian fields\nand the lake of Ciminus with its mountain and the groves of Capena.",
 "Some are the ranks of Fescennium and the Aequi Falisci; some hold the heights of Soracte and the fields of Flavina, the lake and mountain of Ciminus, and the groves of Capena.",
 """'Hi… Hi', 'these… these', or 'some… others': the peoples Messapus leads, all from southern Etruria near Rome. Fescennium gave its name to the ribald 'Fescennine verses' sung at weddings; the Aequi Falisci are the Faliscans of Falerii. Soracte is the lone mountain north of Rome (Horace's 'Vides ut alta stet nive candidum Soracte'); Mount Ciminus stands over its crater lake (Lago di Vico); Capena had a famous grove of Feronia. Greenough prints a full stop after 'Faliscos' and a capital 'Hi', so line 695 stands without a verb and 'habent' must be supplied from 696; most editions have a comma here. It is doubtful whether the stop is a misprint, since the capital that follows agrees with it, so the print is kept as it stands, and the two lines are taken as one unit with 'habent' governing both."""),
(702, 'palus.',
 "They went in even ranks and sang their king,\nas once snowy swans among the clear clouds,\nwhen they bring themselves back from feeding, and through their long necks tuneful\nmeasures they utter; the river sounds, and the Asian marsh, far off\nsmitten.",
 "They marched in measured step, singing of their king, like snow-white swans among the clear clouds when they come home from feeding and pour out tuneful strains through their long throats, and the river and the Asian marsh echo far and wide with the sound.",
 """'aequati numero', 'levelled in number', marching in step and in even ranks, keeping time as they sing. 'regem… canebant', 'they sang (of) their king', the accusative of the theme sung. The simile of swans comes from Homer, who compares the Greek host pouring onto the plain to flocks of geese, cranes and long-necked swans in the 'Asian meadow' by the river Cayster in Lydia (Iliad 2, just before his catalogue); 'Asia palus' (with long A, from the adjective 'Asius') is that marsh. 'liquida… nubila', 'clear, limpid clouds'. 'sese… referunt', 'bring themselves back', 'return'. 'longa… per colla', 'through their long necks'. 'pulsa palus', 'the marsh, struck' by the sound. Line 702 is a half-line, one of the unfinished lines Virgil left in the poem at his death; the sense ends with it. Swans were thought to sing, and some have heard in them a compliment to Ennius, Messapus's descendant and the swan of early Latin verse."""),
(705, 'nubem.',
 "Nor would anyone bronze-clad battle-lines, from a host so great,\nthink were being massed, but an airy, from the deep flood,\nbeing driven, of hoarse birds, to the shores, a cloud.",
 "No one would have thought that bronze-armed battalions were massing out of so vast a host, but rather that a cloud of harsh-voiced birds was sweeping in from the open sea towards the shore.",
 """'Nec quisquam… putet', 'nor would anyone think', the potential subjunctive. 'aeratas acies… misceri', accusative and infinitive, 'that bronze-clad lines were being mustered'; and set against it 'aeriam… nubem… urgueri', 'that an airy cloud was being driven': Virgil plays on 'aeratas' and 'aeriam', bronze and air. 'volucrum raucarum', 'of hoarse-voiced birds', the swans' song turned to a clamour. 'gurgite ab alto', 'from the deep sea'. 'urgueri' is Greenough's spelling of 'urgeri'. The Latin Library reads 'examine', 'swarm', for 'ex agmine', 'out of the host', which would make the birds' swarm the subject of the picture; Greenough's reading is kept. The catalogue continues with Clausus in the next part."""),
]

P = A.part('aeneid-055'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
